UPDATE vault_record_grant SET status='revoked',version=version+1,updated_at=unixepoch() WHERE account_id=?1 AND origin=?2 AND vault_id=?3 AND collection_id=?4 AND record_id=?5 AND kind=?6 AND record_revision=?7 AND ciphertext_sha256=?8 AND key_generation=?9 AND owner_key_revision=?10 AND version=?13 AND status='active' AND EXISTS(SELECT 1 FROM sso_context sx JOIN sso_session ss ON ss.sso_id=sx.sso_id JOIN account_security a ON a.account_id=ss.account_id JOIN credential c ON c.account_id=ss.account_id AND c.credential_id=ss.credential_id WHERE sx.secret_hash=?12 AND ss.account_id=?1 AND ss.credential_id=?11 AND ss.revoked=0 AND ss.expires_at>unixepoch() AND a.active=1 AND a.epoch=ss.epoch AND c.active=1)
